INSERT INTO `score_audit_history` VALUES (40,4041,2026,1041,'APPEAL_APPLY','本人在实习期间作为核心骨干完成了企业核心架构优化，并提交了软件著作权佐证，建议酌情调高企业与综合评分。','https://oss.college.edu.cn/appeals/cert_1041.pdf','{\"finalScore\":82.00,\"scoreLevel\":\"GOOD\"}',NULL,1041,'压测学生041','学生在公示期提交异议申诉',NULL,'2026-09-22 18:00:00'),(41,4042,2026,1042,'APPEAL_REJECT','申诉原由核查',NULL,'{\"finalScore\":83.00,\"scoreLevel\":\"GOOD\"}',NULL,1201,'计算机院系主管（压测）','经院系教学督导组与企业核实，学生参与度符合原评分区间，维持原评定成绩不变。',NULL,'2026-09-22 18:00:00'),(42,4043,2026,1043,'APPEAL_PASS','申请重核企业加分项','https://oss.college.edu.cn/appeals/doc_1043.pdf','{\"finalScore\":82.00,\"scoreLevel\":\"GOOD\"}','{\"finalScore\":91.50,\"scoreLevel\":\"EXCELLENT\"}',1201,'计算机院系主管（压测）','经院系督导委员会线下复核通过，依据红头批件予以相应加分调整。','JW-2026-088','2026-09-22 18:00:00');
